import React from 'react';
import { AppProvider } from '@shopify/polaris';
import { Provider as AppBridgeProvider } from '@shopify/app-bridge-react';
import '@shopify/polaris/build/esm/styles.css';
import './App.css';
import Routes from './Routes';

// Make sure environment variables exist or provide defaults
const apiKey = process.env.REACT_APP_SHOPIFY_API_KEY || '';
const host = process.env.REACT_APP_SHOPIFY_HOST || '';

const config = {
  apiKey,
  host,
  forceRedirect: true
};

function App() {
  // Add check to ensure required values are available
  if (!apiKey || !host) {
    return (
      <div className="error-container">
        <h1>Configuration Error</h1>
        <p>Missing required environment variables. Please set REACT_APP_SHOPIFY_API_KEY and REACT_APP_SHOPIFY_HOST in your .env file.</p>
      </div>
    );
  }

  return (
    <AppBridgeProvider config={config}>
      <AppProvider i18n={{}}>
        <Routes />
      </AppProvider>
    </AppBridgeProvider>
  );
}

export default App;